ruleToc.chapterList:
@js:
var path1="@@.margin_right@a@href";
var path2="@@.chapter@a.0@href";
var i=java.getString(path1);
var d=java.getString(path2);
i=String(i);d=String(d);
var url=i.replace(/\d+.html/,"");
var start=i.match(/(\d+).html/)[1];
var ends=d.match(/(\d+).html/)[1];
var list=[{text:"第1章",href:i}];
if(ends-start<10000){
	for(var c=1;start<=ends;c++,start++){
	list.push({text:`第${c}章`,href:url+start+".html"})
	}
	list;
}else{
	java.toast("目录异常，获取失败！")
	list=[{text:"正文",href:i}]
	list;
	}

ruleContent.nextContentUrl:
@js:
try{
page=result.match(/\(\d*\/(\d*)\)/)[1];
//java.log(page)
list=[];
if(page>=2){
for(var i=2;i<=page;i++){
href=baseUrl.replace(/(_\d*)?.html/,"_"+i+".html");
list.push(href);
}
}
list
}catch(e){java.getString('@@.section-opt a@href')}

ruleToc.chapterList:
.panel-chapterlist.0@dd@a
@js:
var r = result, n = 0;
Array.from(r, (x, i) => {
	var name = x.text(),
	link = x.attr("href");
	dir = {text: name, href: link,
	toString: function(){
		return JSON.stringify(this)}
	};
	if(/javascript/i.test(x) && (a = r[i + 1]) ){
		msg = "目录缺失，尝试修复中，稍等！";
		n += 1; n < 2 && java.log(msg);
		 //java.toast(msg)
			var ah = a.attr("href"), 
			url = /^https?/.test(ah) ? 
			ah : book.origin + ah;
			var h = java.ajax(url);
			path = "text.上一@href";
		u = java.getString(path, h);
		dir.href = u;
		//java.log(dir.toString())
		}
	return dir
	});

